// src/routes.ts
var ROUTES = {
  PRODUCTS: "/products",
  LOGIN: "/login",
  CART: "/cart",
  ORDERS: "/orders",
  HOME: "/"
};

// src/events.ts
var EVENTS = {
  AUTH_CHANGED: "mfe:auth-changed",
  CART_UPDATED: "mfe:cart-updated",
  ORDER_PLACED: "mfe:order-placed"
};

// src/keys.ts
var STORAGE_KEYS = {
  AUTH_TOKEN: "mfe_auth_token",
  USER_DATA: "mfe_user_data",
  RETURN_URL: "mfe_return_url",
  CART_DATA: "mfe_cart_items",
  ORDERS_DATA: "mfe_orders"
};

// src/storage.ts
function getToken() {
  if (typeof window === "undefined") return null;
  return localStorage.getItem(STORAGE_KEYS.AUTH_TOKEN);
}
function getStoredUser() {
  if (typeof window === "undefined") return null;
  const raw = localStorage.getItem(STORAGE_KEYS.USER_DATA);
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}
function setStoredUser(user) {
  if (typeof window === "undefined") return;
  localStorage.setItem(STORAGE_KEYS.USER_DATA, JSON.stringify(user));
}
function clearStoredUser() {
  if (typeof window === "undefined") return;
  localStorage.removeItem(STORAGE_KEYS.USER_DATA);
}
function setToken(token) {
  localStorage.setItem(STORAGE_KEYS.AUTH_TOKEN, token);
  window.dispatchEvent(new CustomEvent("mfe:auth-changed"));
}
function clearToken() {
  localStorage.removeItem(STORAGE_KEYS.AUTH_TOKEN);
  clearStoredUser();
  window.dispatchEvent(new CustomEvent("mfe:auth-changed"));
}
function isAuthenticated() {
  const t = getToken();
  return !!t && t.length > 0;
}
function getReturnUrl() {
  const params = new URLSearchParams(window.location.search);
  return params.get("returnUrl") || "/products";
}
export {
  EVENTS,
  ROUTES,
  STORAGE_KEYS,
  clearStoredUser,
  clearToken,
  getReturnUrl,
  getStoredUser,
  getToken,
  isAuthenticated,
  setStoredUser,
  setToken
};
